//! Strata core: vault format, crypto, merge, and sync logic.
//!
//! Everything security-critical lives in this crate. The Kotlin side is UI and
//! thin platform adapters only (see `protector::PlatformProtector`).
//! Bindings are generated by UniFFI; see `uniffi.toml`.

uniffi::setup_scaffolding!();

pub mod policy;
pub mod protector;

/// Version of the core library, so the UI can confirm the native library loaded.
#[uniffi::export]
pub fn core_version() -> String {
    env!("CARGO_PKG_VERSION").to_string()
}
